-- V8: 课程内容重构为图文穿插教程风格
-- 配图路径：/uploads/images/course-content/c{课程ID}_{序号}.jpg
-- 用户需自行将图片放到 uploads/images/course-content/ 目录

UPDATE `course_info` SET `content` = '<h3>一、为什么要做养老金资格认证</h3><p>每年都要做一次养老金资格认证，证明自己健在，才能继续领取养老金。</p><p>以前要去社区排队办理，现在用手机几分钟就能完成，不用出门。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c1_1.jpg" alt="养老金资格认证的意义" style="max-width:100%;border-radius:8px;" /></p><h3>二、认证前要准备什么</h3><p>准备好身份证、社保卡，确认手机能正常使用摄像头。</p><p>找一个光线明亮的地方，摘下帽子和墨镜，方便人脸识别。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c1_2.jpg" alt="准备身份证和社保卡" style="max-width:100%;border-radius:8px;" /></p><h3>三、操作步骤详解</h3><p>打开掌上12333APP或当地人社APP，登录后找到待遇资格认证。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c1_3.jpg" alt="打开掌上12333找到待遇资格认证" style="max-width:100%;border-radius:8px;" /></p><p>点击开始认证，输入身份证号，确认个人信息无误。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c1_4.jpg" alt="输入身份证号确认信息" style="max-width:100%;border-radius:8px;" /></p><p>把脸对准手机摄像头，按提示眨眼或转头，完成人脸识别。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c1_5.jpg" alt="对准摄像头完成人脸识别" style="max-width:100%;border-radius:8px;" /></p><h3>四、没有智能手机怎么办</h3><p>可以让子女在他们的手机上帮忙认证，添加亲情账号即可。</p><p>也可以去社区服务中心或社保局，让工作人员协助办理。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c1_6.jpg" alt="子女帮忙认证或去社区办理" style="max-width:100%;border-radius:8px;" /></p><h3>五、常见问题解答</h3><p>认证不通过时别着急，多试几次，光线太暗或戴眼镜都可能影响识别。</p><p>每年认证时间以当地通知为准，一般是一年一次，别错过。</p>' WHERE `id` = 1;

UPDATE `course_info` SET `content` = '<h3>一、什么是医保电子凭证</h3><p>医保电子凭证就是电子版的医保卡，看病买药刷手机就行，不用带实体卡。</p><p>全国通用，安全方便，是医保线上业务的唯一身份凭证。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c2_1.jpg" alt="医保电子凭证介绍" style="max-width:100%;border-radius:8px;" /></p><h3>二、申领前要准备什么</h3><p>准备好身份证和社保卡，确认本人实名注册过微信或支付宝。</p><p>手机要能正常使用，能接收短信验证码。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c2_2.jpg" alt="准备身份证和社保卡" style="max-width:100%;border-radius:8px;" /></p><h3>三、激活步骤详解</h3><p>打开微信，搜索国家医保局或医保电子凭证小程序。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c2_3.jpg" alt="微信搜索医保电子凭证小程序" style="max-width:100%;border-radius:8px;" /></p><p>点击激活凭证，输入身份证号，进行人脸识别验证身份。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c2_4.jpg" alt="点击激活凭证进行人脸识别" style="max-width:100%;border-radius:8px;" /></p><p>验证通过后设置密码，激活成功，凭证会保存在微信卡包里。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c2_5.jpg" alt="设置密码激活成功" style="max-width:100%;border-radius:8px;" /></p><h3>四、日常怎么使用</h3><p>去医院看病时，打开微信卡包找到医保电子凭证，出示二维码扫码即可。</p><p>去药店买药也一样，出示二维码就能结算，非常方便。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c2_6.jpg" alt="出示二维码扫码结算" style="max-width:100%;border-radius:8px;" /></p><h3>五、常见问题解答</h3><p>激活失败时检查身份证号是否填对，人脸识别时摘掉眼镜和口罩。</p><p>换了手机不用重新激活，登录微信后凭证会自动同步过来。</p>' WHERE `id` = 2;

UPDATE `course_info` SET `content` = '<h3>一、视频通话能做什么</h3><p>微信视频通话能让你和远方的家人面对面聊天，看到对方的样子。</p><p>免费使用，只要有网络就能打，比打电话更亲切。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c3_1.jpg" alt="微信视频通话的好处" style="max-width:100%;border-radius:8px;" /></p><h3>二、通话前要检查什么</h3><p>确认手机连上了网络，无线网或流量都行，信号要稳定。</p><p>检查摄像头没有被遮挡，前摄像头能拍到自己。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c3_2.jpg" alt="检查网络和摄像头" style="max-width:100%;border-radius:8px;" /></p><h3>三、单人视频通话步骤</h3><p>打开微信，找到要视频的联系人，点进聊天界面。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c3_3.jpg" alt="打开微信找到联系人聊天" style="max-width:100%;border-radius:8px;" /></p><p>点右下角加号，选择视频通话，再选视频通话。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c3_4.jpg" alt="点加号选择视频通话" style="max-width:100%;border-radius:8px;" /></p><p>等对方接听，就能看到对方了。通话结束点红色挂断键。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c3_5.jpg" alt="对方接通后开始视频通话" style="max-width:100%;border-radius:8px;" /></p><h3>四、怎么发起群视频</h3><p>在群聊里点右下角加号，选视频通话，再选通话成员。</p><p>勾选要一起视频的群友，点右上角完成，等大家接通。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c3_6.jpg" alt="群聊发起视频通话选择成员" style="max-width:100%;border-radius:8px;" /></p><h3>五、实用小技巧</h3><p>听不清时可以开免提，点屏幕上的喇叭图标放大声音。</p><p>光线不好时可以切换摄像头，点翻转图标用后摄像头拍风景。</p>' WHERE `id` = 3;

UPDATE `course_info` SET `content` = '<h3>一、为什么要学调字体和声音</h3><p>年纪大了眼睛花、耳朵背，手机默认字体小、声音小，看着费劲。</p><p>学会调整后，字大了看得清，声音大了听得明，用手机更轻松。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c4_1.jpg" alt="调大字体方便老人使用" style="max-width:100%;border-radius:8px;" /></p><h3>二、调整系统字体大小</h3><p>打开手机设置，找到显示或显示与亮度选项。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c4_2.jpg" alt="打开设置找到显示选项" style="max-width:100%;border-radius:8px;" /></p><p>点击字体大小，把滑块往右拉，字就变大了，选合适的大小。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c4_3.jpg" alt="拉动滑块调大字体" style="max-width:100%;border-radius:8px;" /></p><h3>三、调整手机声音</h3><p>按手机侧面的音量键，把铃声调大，能清楚听到来电。</p><p>在设置里找到声音，把铃声、闹钟、媒体音量都调大。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c4_4.jpg" alt="按音量键调大铃声" style="max-width:100%;border-radius:8px;" /></p><h3>四、调大微信聊天字体</h3><p>打开微信，点右下角我，再点设置，找到通用。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c4_5.jpg" alt="微信我设置通用" style="max-width:100%;border-radius:8px;" /></p><p>点字体大小，把滑块往右拉，聊天字就变大了。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c4_6.jpg" alt="微信字体大小滑块往右拉" style="max-width:100%;border-radius:8px;" /></p><h3>五、无障碍功能帮助</h3><p>在设置里搜无障碍，开启放大功能或随选朗读。</p><p>放大功能点三下屏幕就能放大字，随选朗读能让手机读出文字。</p>' WHERE `id` = 4;

UPDATE `course_info` SET `content` = '<h3>一、为什么要学防骗</h3><p>骗子最爱盯老人，电话、短信、网络处处是陷阱，一不留神钱就没了。</p><p>学会识破套路，守住养老钱，安享晚年。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c5_1.jpg" alt="电信诈骗盯上老人" style="max-width:100%;border-radius:8px;" /></p><h3>二、五类高发骗局</h3><p>第一类是冒充公检法，说涉嫌犯罪要转账安全账户，全是假的。</p><p>第二类是冒充亲友出事，说孩子住院要打钱，一定先打电话核实。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c5_2.jpg" alt="冒充公检法和亲友诈骗" style="max-width:100%;border-radius:8px;" /></p><p>第三类是中奖退税，说要先交手续费才能领奖，都是骗局。</p><p>第四类是保健品推销，夸大功效骗老人买高价产品。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c5_3.jpg" alt="中奖退税和保健品骗局" style="max-width:100%;border-radius:8px;" /></p><p>第五类是冒充客服退款，说商品有问题要退款，让你点链接转账。</p><h3>三、真实案例警示</h3><p>张奶奶接到电话说孙子出车祸，急急忙忙转了三万块，事后才发现被骗。</p><p>李爷爷被冒充警察吓唬，把养老钱转到了安全账户，全部损失。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c5_4.jpg" alt="老人被骗真实案例" style="max-width:100%;border-radius:8px;" /></p><h3>四、记住防骗口诀</h3><p>陌生电话不轻信，要钱转账多核实，天上不会掉馅饼，遇事先把子女问。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c5_5.jpg" alt="防骗口诀四句话" style="max-width:100%;border-radius:8px;" /></p><h3>五、遇到可疑电话怎么办</h3><p>不要慌，不要按对方说的做，直接挂断电话。</p><p>拿不准的事，先打110报警或问子女，千万别自己急着转账。</p>' WHERE `id` = 5;

UPDATE `course_info` SET `content` = '<h3>一、为什么要用手机挂号</h3><p>手机挂号不用去医院排队，在家就能挂上号，省时省力。</p><p>能提前选好医生和时间，避免白跑一趟挂不到号。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c6_1.jpg" alt="手机挂号不用排队" style="max-width:100%;border-radius:8px;" /></p><h3>二、预约前要准备什么</h3><p>准备好身份证、医保卡，记清楚要挂哪个科、哪位医生。</p><p>确认手机上有微信或支付宝，已经实名认证过。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c6_2.jpg" alt="准备身份证医保卡" style="max-width:100%;border-radius:8px;" /></p><h3>三、挂号操作步骤</h3><p>打开微信，搜索要去的医院公众号或小程序，关注后进入。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c6_3.jpg" alt="搜索医院公众号" style="max-width:100%;border-radius:8px;" /></p><p>点预约挂号，选科室、选医生、选日期和时间段。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c6_4.jpg" alt="选科室医生和时间" style="max-width:100%;border-radius:8px;" /></p><p>填好就诊人信息，确认后提交，付款成功就挂号完成了。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c6_5.jpg" alt="填写信息付款挂号成功" style="max-width:100%;border-radius:8px;" /></p><h3>四、就诊与取消挂号</h3><p>就诊当天提前到院，用身份证或医保卡在自助机取号。</p><p>去不了要及时取消，在公众号里点我的挂号取消，把号让给别人。</p><h3>五、温馨提示</h3><p>热门专家号要提前几天抢，定好闹钟准点挂。</p><p>不要信黄牛代挂，加价挂号都是骗局，有号也白搭。</p>' WHERE `id` = 6;

UPDATE `course_info` SET `content` = '<h3>一、什么是异地就医备案</h3><p>异地备案就是告诉医保部门，你要去外地看病，这样报销更方便。</p><p>办了备案，在外地医院看病能直接刷卡结算，不用来回跑报销。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c7_1.jpg" alt="异地就医备案说明" style="max-width:100%;border-radius:8px;" /></p><h3>二、哪些情况需要备案</h3><p>去外地子女家长住、冬天去南方过冬、转院到外地大医院看病。</p><p>这些情况都要先办备案，不备案在外地看病报销麻烦。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c7_2.jpg" alt="异地居住和转院需备案" style="max-width:100%;border-radius:8px;" /></p><h3>三、线上备案步骤</h3><p>打开微信搜索国家异地就医备案小程序，进入后选快速备案。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c7_3.jpg" alt="搜索国家异地就医备案小程序" style="max-width:100%;border-radius:8px;" /></p><p>选为自己备案，填好参保地、就医地、备案类型等信息。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c7_4.jpg" alt="填写参保地和就医地" style="max-width:100%;border-radius:8px;" /></p><p>上传身份证或承诺书，人脸识别确认后提交，等审核通过。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c7_5.jpg" alt="上传材料人脸识别提交" style="max-width:100%;border-radius:8px;" /></p><h3>四、备案后怎么看病</h3><p>备案通过后，在外地定点医院看病，出示医保电子凭证就能直接结算。</p><p>个人只付该付的部分，报销部分医院直接扣，不用拿回老家报。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c7_6.jpg" alt="出示凭证直接结算" style="max-width:100%;border-radius:8px;" /></p><h3>五、常见问题解答</h3><p>备案一般两三个工作日就通过，急用可办紧急备案。</p><p>备案有有效期，到期或换地方要重新办，别忘记续。</p>' WHERE `id` = 7;

UPDATE `course_info` SET `content` = '<h3>一、什么是电子社保卡</h3><p>电子社保卡是实体社保卡的线上版，扫码就能用，不用带卡出门。</p><p>和实体卡功能一样，还能查社保、办业务，更方便。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c8_1.jpg" alt="电子社保卡介绍" style="max-width:100%;border-radius:8px;" /></p><h3>二、领取前要准备什么</h3><p>要先有实体社保卡，并且已经激活过。</p><p>手机上要有微信或支付宝，已经实名认证过本人身份。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c8_2.jpg" alt="准备实体社保卡" style="max-width:100%;border-radius:8px;" /></p><h3>三、领取步骤详解</h3><p>打开微信，搜索电子社保卡小程序，点击领取电子社保卡。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c8_3.jpg" alt="微信搜索电子社保卡" style="max-width:100%;border-radius:8px;" /></p><p>输入姓名身份证号，进行人脸识别验证身份。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c8_4.jpg" alt="输入信息人脸识别" style="max-width:100%;border-radius:8px;" /></p><p>验证通过后设置密码，领取成功，卡面保存在微信卡包里。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c8_5.jpg" alt="设置密码领取成功" style="max-width:100%;border-radius:8px;" /></p><h3>四、常用四项功能</h3><p>一是查社保缴费记录，看自己交了多少年、每月交多少。</p><p>二是查养老金待遇，看每月养老金到账情况。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c8_6.jpg" alt="查缴费记录和养老金" style="max-width:100%;border-radius:8px;" /></p><p>三是办失业工伤待遇，四是扫码就医购药，出示二维码就行。</p><h3>五、安全提醒</h3><p>密码不要告诉别人，手机丢了要尽快挂失补办社保卡。</p><p>验证码不能给任何人，自称社保局要验证码的都是骗子。</p>' WHERE `id` = 8;

UPDATE `course_info` SET `content` = '<h3>一、学完能做什么</h3><p>学会微信收发红包和付款，过年给孙辈发红包、买东西扫码付款都行。</p><p>不用找零、不用带现金，一部手机全搞定。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c9_1.jpg" alt="微信收发红包和付款" style="max-width:100%;border-radius:8px;" /></p><h3>二、怎么发红包</h3><p>打开和对方的聊天，点右下角加号，选择红包。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c9_2.jpg" alt="点加号选择红包" style="max-width:100%;border-radius:8px;" /></p><p>输入金额和个数，写上祝福语，点塞钱进红包。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c9_3.jpg" alt="输入金额塞钱进红包" style="max-width:100%;border-radius:8px;" /></p><p>输入支付密码确认，红包就发出去了，对方点击就能拆。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c9_4.jpg" alt="输密码红包发出" style="max-width:100%;border-radius:8px;" /></p><h3>三、收红包和查零钱</h3><p>收到红包点开拆，钱自动存进微信零钱。</p><p>点我再点服务里的钱包，能看到零钱余额。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c9_5.jpg" alt="我钱包查看零钱" style="max-width:100%;border-radius:8px;" /></p><h3>四、扫码付款</h3><p>买东西时，点微信右上角加号选扫一扫，扫商家二维码。</p><p>输入金额，输支付密码确认，钱就付好了。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c9_6.jpg" alt="扫一扫输密码付款" style="max-width:100%;border-radius:8px;" /></p><h3>五、安全提醒</h3><p>付款前看清金额，确认收款方是自己认识的人或正规商家。</p><p>不要扫陌生人发的二维码，可能有病毒或盗刷风险。</p>' WHERE `id` = 9;

UPDATE `course_info` SET `content` = '<h3>一、手机拍照的好处</h3><p>手机随身带，随时能拍，记录生活美好瞬间，留下回忆。</p><p>拍完就能发给子女看，不用洗照片，省钱又方便。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c10_1.jpg" alt="手机拍照记录生活" style="max-width:100%;border-radius:8px;" /></p><h3>二、拍照小技巧</h3><p>打开相机，点屏幕下方圆形拍照键就能拍，横着拿手机拍风景更好看。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c10_2.jpg" alt="打开相机点拍照键" style="max-width:100%;border-radius:8px;" /></p><p>点击屏幕可以对焦，画面会变清晰，光线足时拍出来更亮。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c10_3.jpg" alt="点击屏幕对焦" style="max-width:100%;border-radius:8px;" /></p><h3>三、查看和删除照片</h3><p>点相机左下角小图，或打开相册APP，就能看到所有照片。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c10_4.jpg" alt="打开相册查看照片" style="max-width:100%;border-radius:8px;" /></p><p>不要的照片长按选中，点删除就能删掉，腾出空间。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c10_5.jpg" alt="长按删除不要的照片" style="max-width:100%;border-radius:8px;" /></p><h3>四、内存不足怎么办</h3><p>手机提示存储不足时，先删重复和模糊的照片。</p><p>重要的照片发给子女让他们存好，或备份到云空间，本地就能删。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c10_6.jpg" alt="删照片或备份到云端" style="max-width:100%;border-radius:8px;" /></p><h3>五、分享给家人</h3><p>在相册里点开照片，点下方分享图标，选微信发给子女。</p><p>也能一次选多张，一起发过去，让家人看到你的生活。</p>' WHERE `id` = 10;

UPDATE `course_info` SET `content` = '<h3>一、为什么要做安全设置</h3><p>微信钱包里有零钱，绑了银行卡，不设安全等于把钱敞着放。</p><p>做好安全设置，即使手机丢了别人也动不了你的钱。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c11_1.jpg" alt="微信支付安全很重要" style="max-width:100%;border-radius:8px;" /></p><h3>二、设置支付密码</h3><p>打开微信，点我再点服务，进入钱包。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c11_2.jpg" alt="我服务钱包" style="max-width:100%;border-radius:8px;" /></p><p>点支付设置，设好6位支付密码，用自己记得住但不简单的数字。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c11_3.jpg" alt="设置6位支付密码" style="max-width:100%;border-radius:8px;" /></p><h3>三、开启指纹刷脸支付</h3><p>在支付设置里找到指纹支付或面容支付，点开启。</p><p>按提示录入指纹或刷脸，以后付款用指纹刷脸更安全方便。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c11_4.jpg" alt="开启指纹或刷脸支付" style="max-width:100%;border-radius:8px;" /></p><h3>四、设置支付限额</h3><p>在支付设置里找到转账到账时间和额度设置。</p><p>把单笔和单日限额调小一些，即使被盗刷损失也有限。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c11_5.jpg" alt="设置支付限额" style="max-width:100%;border-radius:8px;" /></p><h3>五、防骗自查</h3><p>定期看账单里的消费记录，发现不明支出马上改密码。</p><p>不要把支付密码告诉任何人，包括自称客服和警察的人。</p>' WHERE `id` = 11;

UPDATE `course_info` SET `content` = '<h3>一、为什么骗子专盯老人</h3><p>老人怕生病、爱惜命、又有积蓄，容易被养生忽悠。</p><p>子女不在身边没人商量，骗子就趁虚而入套近乎。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c12_1.jpg" alt="骗子盯上老人养老钱" style="max-width:100%;border-radius:8px;" /></p><h3>二、骗子的四步洗脑法</h3><p>第一步送鸡蛋送温暖，套近乎博好感，让你放松警惕。</p><p>第二步开养生讲座，夸大病情吓唬你，说不吃产品会出大事。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c12_2.jpg" alt="送鸡蛋和讲座洗脑" style="max-width:100%;border-radius:8px;" /></p><p>第三步找病友现身说法，吹产品多神奇。</p><p>第四步限时优惠催你掏钱，说今天不买明天涨价。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c12_3.jpg" alt="病友现身说法催掏钱" style="max-width:100%;border-radius:8px;" /></p><h3>三、三招识破骗局</h3><p>第一招看资质，正规保健品有蓝帽标志，问清批号查真假。</p><p>第二招看价格，几千上万的产品正常药店几百块就能买到。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c12_4.jpg" alt="看蓝帽标志和价格" style="max-width:100%;border-radius:8px;" /></p><p>第三招问医生，真有病该去医院，别信保健品能治病。</p><h3>四、真实案例警示</h3><p>王爷爷买了两万块神药，吃完没效果才发现是普通食品。</p><p>刘奶奶被送鸡蛋吸引，听讲座后花光积蓄，子女才发现。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c12_5.jpg" alt="老人买保健品被骗案例" style="max-width:100%;border-radius:8px;" /></p><h3>五、被纠缠怎么办</h3><p>别去参加免费讲座和旅游，免费的往往最贵。</p><p>缠着不让走就打110或叫子女来接，别一个人硬扛。</p>' WHERE `id` = 12;

UPDATE `course_info` SET `content` = '<h3>一、为什么要辨别谣言</h3><p>网上假消息满天飞，老人分辨不清容易信，转发还害别人。</p><p>信了谣言可能乱吃偏方伤身体，也可能被骗钱。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c13_1.jpg" alt="网络谣言满天飞" style="max-width:100%;border-radius:8px;" /></p><h3>二、谣言的三件外衣</h3><p>第一件是震惊体，标题写震惊、速看、删前快看，故意吓唬人。</p><p>第二件是伪权威，冒充央视、专家名义，看着唬人。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c13_2.jpg" alt="震惊体和伪权威" style="max-width:100%;border-radius:8px;" /></p><p>第三件是情感绑架，说是中国人就转、为了家人必须看，逼你传播。</p><h3>三、三步核实法</h3><p>第一步看来源，正规媒体发的有据可查，来源不明要多留心。</p><p>第二步搜一搜，把关键词复制到百度搜，看有没有权威辟谣。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c13_3.jpg" alt="看来源和搜索核实" style="max-width:100%;border-radius:8px;" /></p><p>第三步问子女，拿不准就发给子女问问，年轻人会查。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c13_4.jpg" alt="问子女帮忙核实" style="max-width:100%;border-radius:8px;" /></p><h3>四、小心这些消息</h3><p>某种食物致癌、某偏方能治百病、某地发生了什么大事，多半是假的。</p><p>要求转发给多少人否则会怎样的，百分百是谣言，别信。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c13_5.jpg" alt="常见谣言类型" style="max-width:100%;border-radius:8px;" /></p><h3>五、看到谣言怎么做</h3><p>不转发不传播，不确定就别点转发键。</p><p>可以举报谣言，点文章右上角举报，让平台处理。</p>' WHERE `id` = 13;

UPDATE `course_info` SET `content` = '<h3>一、什么是刷单骗局</h3><p>刷单就是商家找人假装买东西刷好评，骗子借这名义骗钱。</p><p>先给你小甜头尝尝，等你信了投大钱，就血本无归。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c14_1.jpg" alt="刷单返利骗局" style="max-width:100%;border-radius:8px;" /></p><h3>二、骗子的五步流程</h3><p>第一步群发广告，说动动手指日赚几百，加群领任务。</p><p>第二步让你垫付小钱刷单，连本带佣金返给你，建立信任。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c14_2.jpg" alt="群发广告垫付小钱" style="max-width:100%;border-radius:8px;" /></p><p>第三步让你加大投入，说有大单、连单佣金更高。</p><p>第四步找理由不返钱，说任务没完成要继续刷，越陷越深。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c14_3.jpg" alt="加大投入不返钱" style="max-width:100%;border-radius:8px;" /></p><p>第五步拉黑跑路，你的钱全进了骗子口袋。</p><h3>三、为什么刷单违法</h3><p>刷单是虚假交易，违反电商法和反不正当竞争法，是违法行为。</p><p>参与刷单不仅被骗钱，还可能承担法律责任，得不偿失。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c14_4.jpg" alt="刷单违法后果" style="max-width:100%;border-radius:8px;" /></p><h3>四、高发变种</h3><p>有点赞返利、看视频赚钱、做任务领红包等变种，套路一样。</p><p>还有冒充快递理赔、公益捐款返利，都是刷单骗局换皮。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c14_5.jpg" alt="刷单骗局各种变种" style="max-width:100%;border-radius:8px;" /></p><h3>五、防骗要点</h3><p>记住天上不会掉馅饼，轻松赚钱的好事轮不到陌生人。</p><p>凡是先垫钱后返利的，全是诈骗，遇到就拉黑报警。</p>' WHERE `id` = 14;

UPDATE `course_info` SET `content` = '<h3>一、线上缴费的好处</h3><p>以前要去营业厅排队交水电费，现在手机上几分钟搞定。</p><p>不受时间地点限制，晚上也能交，不用跑腿。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c15_1.jpg" alt="手机缴水电费好处" style="max-width:100%;border-radius:8px;" /></p><h3>二、微信缴费方法</h3><p>打开微信，点我再点服务，找到生活缴费。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c15_2.jpg" alt="我服务生活缴费" style="max-width:100%;border-radius:8px;" /></p><p>选要交的项目，水费、电费、燃气费都有，输入户号。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c15_3.jpg" alt="选项目输入户号" style="max-width:100%;border-radius:8px;" /></p><p>查到欠费金额，输支付密码确认，就交好了。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c15_4.jpg" alt="查欠费输密码缴费" style="max-width:100%;border-radius:8px;" /></p><h3>三、支付宝缴费方法</h3><p>打开支付宝，首页找到生活缴费，操作和微信类似。</p><p>同样选项目、输户号、查欠费、付款，很简单。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c15_5.jpg" alt="支付宝生活缴费" style="max-width:100%;border-radius:8px;" /></p><h3>四、自动缴费提醒</h3><p>可以在缴费页设自动缴费，到期自动扣，不用记日期。</p><p>也能设手机日历提醒，每月固定时间提醒自己缴费。</p><h3>五、常见问题</h3><p>户号在缴费单或催费短信上能找到，记好别输错。</p><p>缴费后一般一两分钟到账，没到账可查缴费记录或打客服。</p>' WHERE `id` = 15;

UPDATE `course_info` SET `content` = '<h3>一、手机出行能做什么</h3><p>用手机能叫网约车上门接送，不用去路边拦车。</p><p>还能查公交到哪了、扫码坐公交地铁，出行更方便。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c16_1.jpg" alt="手机出行功能介绍" style="max-width:100%;border-radius:8px;" /></p><h3>二、怎么叫网约车</h3><p>打开微信搜滴滴出行小程序，或在支付宝搜出行。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c16_2.jpg" alt="微信搜索滴滴出行" style="max-width:100%;border-radius:8px;" /></p><p>输起点和终点，点呼叫，等司机接单。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c16_3.jpg" alt="输入起终点呼叫" style="max-width:100%;border-radius:8px;" /></p><p>看车牌和司机信息，到楼下上车，到达后自动扣款。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c16_4.jpg" alt="看车牌上车自动扣款" style="max-width:100%;border-radius:8px;" /></p><h3>三、公交刷码查车</h3><p>在乘车码小程序里开通当地公交乘车码，上车刷码就行。</p><p>用车来了等APP查公交实时位置，知道车还有几站。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c16_5.jpg" alt="刷码乘车查公交位置" style="max-width:100%;border-radius:8px;" /></p><h3>四、老人专属便利</h3><p>很多城市有老人免费或半价乘车政策，带老年证或开通电子卡。</p><p>网约车有老人版，界面更大更简单，还能让子女代叫车。</p><h3>五、出行安全</h3><p>上车核对车牌，和家人分享行程，让子女看到你的位置。</p><p>夜间少出门，必须出门让子女陪着或叫正规网约车。</p>' WHERE `id` = 16;

UPDATE `course_info` SET `content` = '<h3>一、适合什么情况</h3><p>慢性病复诊开药、小毛病咨询、不愿去医院排队，适合在线问诊。</p><p>急症、重病必须去医院，线上问诊解决不了急重病。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c17_1.jpg" alt="在线问诊适合情况" style="max-width:100%;border-radius:8px;" /></p><h3>二、在线问诊步骤</h3><p>打开微信或支付宝，搜互联网医院或医院的线上问诊。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c17_2.jpg" alt="搜索互联网医院" style="max-width:100%;border-radius:8px;" /></p><p>选科室和医生，描述症状或上传检查报告，图文或视频问诊。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c17_3.jpg" alt="选医生描述症状" style="max-width:100%;border-radius:8px;" /></p><p>医生开方后在线付款，选送药上门或就近药店自取。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c17_4.jpg" alt="医生开方付款送药" style="max-width:100%;border-radius:8px;" /></p><h3>三、药店买药</h3><p>在美团或饿了么搜买药，选附近药店下单，外卖送药上门。</p><p>处方药要有医生处方才能买，非处方药直接下单就行。</p><p style="text-align:center;margin:12px 0;"><img src="/uploads/images/course-content/c17_5.jpg" alt="外卖买药送上门" style="max-width:100%;border-radius:8px;" /></p><h3>四、用药安全</h3><p>看清说明书用法用量，别超量、别乱混着吃。</p><p>过期药别吃，存好常用药，慢性病药按时按量吃。</p><h3>五、常见问题</h3><p>在线问诊费用比挂号便宜，能用医保的医院更划算。</p><p>送的药和医院一样正规，有质量问题可联系药店退换。</p>' WHERE `id` = 17;
